def-hyp[predicate](
    Type.annotation(@g, Type.to(Set.im(f@Set.ctxt.f), Set.domain(f@Set.ctxt.f))),
    Eq(g, Set.inv(f)),
    Eq(
        Set.map.graph(g), 
        Set.sep-typed(Type.pair(@y, @x), Type.prod(Set.im(f@Set.ctxt.f), Set.domain(f@Set.ctxt.f)), Eq(y, Type.apply(f@Set.ctxt.f, x)))
    )
)
